public class ScoredDocument
{
    public string Id { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public string ParentDocumentId { get; set; } = string.Empty;
    public double FinalScore { get; set; }
    public Dictionary<string, object> Metadata { get; set; } = new();
}

public static class ReciprocalRankFusion
{
    public static List<ScoredDocument> Merge(
        List<ScoredDocument> keywordResults,
        List<ScoredDocument> vectorResults,
        int kConstant = 60,
        int topCount = 10)
    {
        var scores = new Dictionary<string, (ScoredDocument Doc, double Score)>();

        // 1. Process BM25 Keyword Search rankings
        for (int rank = 0; rank < keywordResults.Count; rank++)
        {
            var doc = keywordResults[rank];
            double contribution = 1.0 / (kConstant + (rank + 1));
            scores[doc.Id] = (doc, contribution);
        }

        // 2. Process HNSW Dense Vector rankings
        for (int rank = 0; rank < vectorResults.Count; rank++)
        {
            var doc = vectorResults[rank];
            double contribution = 1.0 / (kConstant + (rank + 1));
            if (scores.TryGetValue(doc.Id, out var existing))
            {
                scores[doc.Id] = (existing.Doc, existing.Score + contribution);
            }
            else
            {
                scores[doc.Id] = (doc, contribution);
            }
        }

        // 3. Return top results ordered by combined RRF score
        return scores.Values
            .OrderByDescending(x => x.Score)
            .Take(topCount)
            .Select(x => {
                x.Doc.FinalScore = x.Score;
                return x.Doc;
            })
            .ToList();
    }
}

public class SecureRetrievalService
{
    private readonly SearchClient _searchClient;

    public async Task<List<SearchResultItem>> SearchAuthorizedAsync(
        string queryText,
        ReadOnlyMemory<float> queryVector,
        string tenantId,
        IEnumerable<string> userSecurityGroups,
        CancellationToken ct = default)
    {
        // Construct security filter expression:
        // TenantId eq 'tenant-123' and SecurityGroups/any(g: search.in(g, 'group-dev,group-sales'))
        var groupList = string.Join(",", userSecurityGroups);
        var filterExpression = $"TenantId eq '{tenantId}' and SecurityGroups/any(g: search.in(g, '{groupList}'))";

        var searchOptions = new SearchOptions
        {
            Filter = filterExpression,
            Size = 10,
            QueryType = SearchQueryType.Semantic,
            SemanticSearch = new SemanticSearchOptions
            {
                SemanticConfigurationName = "enterprise-semantic-config",
                QueryCaption = new QueryCaption(QueryCaptionType.Extractive)
            }
        };

        // Add vector query for hybrid execution
        searchOptions.VectorSearch = new VectorSearchOptions();
        searchOptions.VectorSearch.Queries.Add(new VectorizedQuery(queryVector)
        {
            KNearestNeighborsCount = 50,
            Fields = { "ContentVector" }
        });

        SearchResults<SearchDocument> response = await _searchClient.SearchAsync<SearchDocument>(
            queryText,
            searchOptions,
            ct);

        var results = new List<SearchResultItem>();
        await foreach (SearchResult<SearchDocument> doc in response.GetResultsAsync())
        {
            results.Add(new SearchResultItem
            {
                DocumentId = doc.Document["DocumentId"].ToString()!,
                Content = doc.Document["Content"].ToString()!,
                Score = doc.Score ?? 0.0,
                RerankerScore = doc.SemanticSearch?.RerankerScore
            });
        }

        return results;
    }
}
